import json
import os
import time
from urllib.request import Request, urlopen

base = os.environ["GRAPH_ENGINE_URL"].rstrip("/")
session_id = os.environ["IGRAPH_SESSION_ID"]
headers = {
    "Content-Type": "application/json",
    "X-User-ID": os.environ["IGRAPH_USER_ID"],
    "X-Session-ID": session_id,
    "X-iGraph-Service-Key": os.environ["IGRAPH_CONTROL_SERVICE_KEY"],
}

def invoke(name, arguments):
    body = json.dumps({"arguments": arguments}).encode("utf-8")
    request = Request(
        f"{base}/sessions/{session_id}/tools/{name}",
        data=body, headers=headers, method="POST",
    )
    with urlopen(request, timeout=900) as response:
        result = json.load(response)
    if result.get("success") is False:
        raise RuntimeError(result)
    return result

def call(name, arguments):
    result = invoke(name, arguments)
    while result.get("async") and result.get("job_id"):
        job_id = result["job_id"]
        while True:
            status = invoke("get_job_status", {"job_id": job_id})
            job = status["job"]
            if job["status"] == "done":
                result = job["result"]
                break
            if job["status"] in {"failed", "cancelled"}:
                raise RuntimeError(job)
            time.sleep(1)
    return result

call("load_graph", {
    "edge_text": "A B 2\nA C 5\nB C 1\nB D 4\nC D 1",
    "append": False,
})
info = call("get_graph_info", {})
path = call("shortest_path", {
    "source": "A", "target": "D", "use_weight": True,
})
assert path["path"] == ["A", "B", "C", "D"]
assert path["total_length"] == 4

preview = call("subgraph_extraction", {
    "method": "node_subset", "nodes": ["A", "B", "C"],
    "create_version": False,
})
view = call("visualize_subgraph", {
    "max_nodes": 50,
    "highlights": {"paths": [{
        "node_sequence": path["path"],
        "label": "Minimum-cost path", "color": "#356ae6",
    }]},
})
print(json.dumps({"path": path, "preview": preview, "view": view}, indent=2))
